package cn.binbin.crm;
import java.util.*;import java.time.*;import java.util.function.Function;import org.springframework.stereotype.Service;import static cn.binbin.crm.TradeService.*;
/** Canonical domain readers, used by automation, extensions and signed APIs. */
@Service
public class P7Records {
 public static final LinkedHashMap<String,String> NAMES=new LinkedHashMap<>();
 public static final Map<String,String> TABLES=Map.ofEntries(Map.entry("CUSTOMER","crm_customer"),Map.entry("LEAD","crm_lead"),Map.entry("OPPORTUNITY","crm_opportunity"),Map.entry("QUOTE","crm_quote"),Map.entry("ORDER","crm_sales_order"),Map.entry("CONTRACT","crm_contract"),Map.entry("RECEIPT","crm_receipt"),Map.entry("TICKET","crm_ticket"),Map.entry("INVOICE","crm_invoice"),Map.entry("EXPENSE","crm_expense"),Map.entry("TARGET","crm_sales_target"),Map.entry("COMMISSION","crm_commission_run"),Map.entry("WEEKLY","crm_sales_weekly_report"),Map.entry("PRODUCT","crm_product"));
 static {String[] ids={"CUSTOMER","LEAD","OPPORTUNITY","QUOTE","ORDER","CONTRACT","RECEIPT","TICKET","INVOICE","EXPENSE","TARGET","COMMISSION","WEEKLY","PRODUCT"};String[] names={"客户","线索","商机","报价","销售订单","合同","回款","服务工单","开票申请","支出","业绩目标","提成核算","销售周报","产品"};for(int i=0;i<ids.length;i++)NAMES.put(ids[i],names[i]);}
 final P3Base b;final P7Permissions p;final CustomerService customers;final BusinessService business;final SalesService sales;final CommerceService commerce;final SalesOrderService orders;final FinanceService finance;final FinanceWorkspaceService fw;final PerformanceService perf;final ServiceDeskService desk;
 public P7Records(P3Base b,P7Permissions p,CustomerService customers,BusinessService business,SalesService sales,CommerceService commerce,SalesOrderService orders,FinanceService finance,FinanceWorkspaceService fw,PerformanceService perf,ServiceDeskService desk){this.b=b;this.p=p;this.customers=customers;this.business=business;this.sales=sales;this.commerce=commerce;this.orders=orders;this.finance=finance;this.fw=fw;this.perf=perf;this.desk=desk;}
 public String type(String type){if(!TABLES.containsKey(type))throw ApiError.bad("业务对象类型无效");return type;}
 public boolean allowed(AuthService.Actor a,String type,boolean write){if(a.supportGrantId()!=null||!p.permits(a,type,write))return false;var t=a.tradeAccess();var c=a.commerceAccess();var s=a.businessAccess();boolean read=switch(type){case "CUSTOMER"->a.canReadCustomers();case "LEAD"->s.leads().read();case "OPPORTUNITY"->s.opportunities().read()&&a.canReadCustomers();case "QUOTE"->c.quotes().read()&&a.canReadCustomers();case "ORDER","CONTRACT","TARGET","COMMISSION","WEEKLY"->t.contracts().read()&&a.canReadCustomers();case "RECEIPT","INVOICE","EXPENSE"->t.contracts().read()&&t.receiptRead()&&a.canReadCustomers();case "PRODUCT"->c.productRead();case "TICKET"->a.p3Access().tickets().read();default->false;};if(!read||!write)return read;return switch(type){case "CUSTOMER"->a.canWriteCustomers();case "LEAD"->s.leads().write();case "OPPORTUNITY"->s.opportunities().write()&&a.canWriteCustomers();case "QUOTE"->c.quotes().write()&&a.canWriteCustomers();case "ORDER","CONTRACT","WEEKLY"->t.contracts().write()&&a.canWriteCustomers();case "TARGET","COMMISSION"->t.contracts().write()&&a.tenant().roles().contains("SALES_MANAGER");case "RECEIPT","INVOICE","EXPENSE"->t.receiptWrite();case "PRODUCT"->c.productWrite();case "TICKET"->a.p3Access().tickets().write();default->false;};}
 public <T>T scope(AuthService.Session s,String type,boolean write,Function<AuthService.Actor,T> fn){type(type);return b.tx.execute(st->{if(write)b.db.queryForObject("SELECT id FROM sys_tenant WHERE id=:tenant FOR UPDATE",map("tenant",s.tenantId()),UUID.class);var a=b.auth.actor(s);p.check(a,type,write);if(!allowed(a,type,write))throw ApiError.forbidden("当前成员没有此业务对象权限");return fn.apply(a);});}
 @SuppressWarnings("unchecked") Map<String,Object> object(Object value){return value instanceof Map<?,?>?(Map<String,Object>)value:b.data.json.convertValue(value,new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});}
 Map<String,Object> get(AuthService.Actor a,String type,UUID id,boolean write){if(!allowed(a,type,write))throw ApiError.forbidden("当前成员没有此对象权限");var s=a.session();Object raw=switch(type){case "CUSTOMER"->customers.get(a,id);case "LEAD"->business.lead(a,id);case "OPPORTUNITY"->sales.opportunity(a,id);case "QUOTE"->commerce.quote(a,id);case "ORDER"->orders.detail(a,id);case "CONTRACT"->b.data.contract(a,id);case "RECEIPT"->finance.receipt(a,id);case "INVOICE"->fw.invoice(a,id);case "EXPENSE"->fw.expense(a,id);case "TARGET","COMMISSION","WEEKLY"->perf.workspaceRecord(a,type,id,write);case "PRODUCT"->commerce.product(a,id);case "TICKET"->desk.ticket(a,id);default->throw ApiError.bad("业务对象类型无效");};var r=new LinkedHashMap<>(object(raw));boolean canWrite=Boolean.TRUE.equals(r.get("canWrite"))||Boolean.TRUE.equals(r.get("canManage"))||Boolean.TRUE.equals(r.get("canLink"));if(type.equals("PRODUCT"))canWrite=a.commerceAccess().productWrite();if(type.equals("EXPENSE"))canWrite=a.tradeAccess().receiptWrite()&&a.tenant().memberId().equals(r.get("createdByMemberId"))&&"DRAFT".equals(r.get("status"));if(write&&!canWrite)throw ApiError.forbidden("无权修改此记录或记录已经锁定");Object title=r.getOrDefault("title",r.getOrDefault("name",r.getOrDefault("companyName",r.getOrDefault("payee",r.getOrDefault("memberName",NAMES.get(type))))));if(type.equals("LEAD"))title=r.get("companyName")+" · "+r.get("name");if(type.equals("TARGET")){Object member=r.get("memberId"),department=r.get("departmentId");String name=member!=null?b.db.queryForObject("SELECT display_name FROM sys_tenant_member WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",member),String.class):b.db.queryForObject("SELECT name FROM org_department WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",department),String.class);r.put("memberName",name);title=name+" · "+r.get("periodStart")+" · 业绩目标";}if(type.equals("COMMISSION")||type.equals("WEEKLY"))title=title+" · "+r.getOrDefault("periodStart",r.get("weekStart"));r.put("recordTitle",title);r.put("entityType",type);r.put("canWrite",canWrite&&allowed(a,type,true));return r;}
 public Object get(AuthService.Session s,String type,UUID id){return scope(s,type,false,a->get(a,type,id,false));}
 public Object catalog(AuthService.Session s){return b.tx.execute(st->{var a=b.auth.actor(s);if(a.supportGrantId()!=null)throw ApiError.forbidden("支持授权不包含业务扩展工作区");var list=NAMES.entrySet().stream().filter(e->allowed(a,e.getKey(),false)).map(e->map("id",e.getKey(),"name",e.getValue(),"canWrite",allowed(a,e.getKey(),true))).toList();return map("objects",list,"administrator",a.admin(),"plan",SaasService.view(p.plan(a)));});}
 public Object list(AuthService.Session s,String type,int page,int size,String q,int year){page(page,size,q);if(year<2000||year>2100)throw ApiError.bad("年份无效");return scope(s,type,false,a->{Object raw=switch(type){case "CUSTOMER"->customers.list(s,page,size,q);case "LEAD"->business.leads(s,page,size,q,"");case "OPPORTUNITY"->sales.opportunities(s,page,size,q,"",null);case "QUOTE"->commerce.quotes(s,page,size,q,"",null,false);case "ORDER"->orders.list(s,page,size,q,"",null);case "CONTRACT"->b.data.contracts(s,page,size,q,"",null,false);case "RECEIPT"->finance.receipts(s,page,size,q,"",null,null,null);case "TICKET"->desk.list(s,page,size,q,"",null,null,"");case "INVOICE"->fw.invoices(s,page,size,q,null);case "EXPENSE"->fw.expenses(s,page,size,q);case "PRODUCT"->commerce.products(s,page,size,q,"");case "TARGET","COMMISSION","WEEKLY"->performancePage(a,type,page,size,q,year);default->throw ApiError.bad("对象类型无效");};var result=object(raw);var items=new ArrayList<Map<String,Object>>();for(Object v:(List<?>)result.get("items")){var r=object(v);var id=UUID.fromString(String.valueOf(r.get("id")));items.add(summary(get(a,type,id,false)));}return map("items",items,"total",result.get("total"),"page",page,"pageSize",size);});}
 private Object performancePage(AuthService.Actor a,String type,int page,int size,String q,int year){var p=b.data.params(a);p.putAll(map("q",q,"year",year,"limit",size,"offset",((long)page-1)*size,"cm",a.tenant().roles().contains("SALES_MANAGER")&&a.tradeAccess().contracts().write()));String table=TABLES.get(type),date=type.equals("WEEKLY")?"week_start":"period_start";String scope=type.equals("COMMISSION")?"(x.member_id=:member OR(:cm AND(:contractReadAll OR(:contractReadDepartment AND m.department_id=:department))))":type.equals("TARGET")?"((x.member_id IS NOT NULL AND(:contractReadAll OR x.member_id=:member OR(:contractReadDepartment AND m.department_id=:department))) OR(x.department_id IS NOT NULL AND(:contractReadAll OR(:contractReadDepartment AND x.department_id=:department))))":"(:contractReadAll OR x.member_id=:member OR(:contractReadDepartment AND m.department_id=:department))";String from=" FROM "+table+" x LEFT JOIN sys_tenant_member m ON m.tenant_id=x.tenant_id AND m.id=x.member_id WHERE x.tenant_id=:tenant AND "+scope+" AND extract(year FROM x."+date+")=:year AND(:q='' OR strpos(lower(coalesce(m.display_name,'')),lower(:q))>0)";return map("items",b.rows("SELECT x.id"+from+" ORDER BY x."+date+" DESC,x.id LIMIT :limit OFFSET :offset",p),"total",b.db.queryForObject("SELECT count(*)"+from,p,Long.class));}
 Map<String,Object> summary(Map<String,Object> r){var v=new LinkedHashMap<String,Object>();for(String k:List.of("id","entityType","recordTitle","version","status","stage","customerId","customerName","ownerMemberId","ownerName","memberId","memberName","assigneeMemberId","createdByMemberId","canWrite","updatedAt","periodStart","weekStart","totalCents","amountCents","targetCents","commissionCents","priceCents"))if(r.containsKey(k))v.put(k,r.get(k));return v;}
 public byte[] export(AuthService.Session s,String type,int year,UUID trace){return scope(s,type,false,a->{if(!a.deliveryAccess().export()||Set.of("ORDER","CONTRACT","RECEIPT","INVOICE","EXPENSE","TARGET","COMMISSION","WEEKLY").contains(type)&&!a.tradeAccess().export()||type.equals("TICKET")&&!a.p3Access().export())throw ApiError.forbidden("无此对象导出权限");var data=new ArrayList<List<Object>>();long total=0;for(int page=1;;page++){var batch=object(list(s,type,page,100,"",year));total=((Number)batch.get("total")).longValue();if(total>5000)throw ApiError.conflict("导出最多5000行，请缩小业务日期范围");for(Object x:(List<?>)batch.get("items")){var r=object(x);Object amount=r.getOrDefault("totalCents",r.getOrDefault("amountCents",r.getOrDefault("targetCents",r.getOrDefault("commissionCents",r.get("priceCents")))));data.add(Arrays.asList(r.get("id"),r.get("recordTitle"),r.get("customerName"),r.getOrDefault("ownerName",r.get("memberName")),r.getOrDefault("status",r.get("stage")),amount,r.get("version")));}if(data.size()>=total)break;}b.audit(a,"WORKSPACE_EXPORTED",type,null,total,trace);return CsvSupport.write(List.of("记录编号","业务名称","客户","负责人","状态","金额（分）","版本"),data);});}
 List<UUID> candidates(AuthService.Actor a,String type,int max){return b.db.queryForList("SELECT id FROM "+TABLES.get(type)+" WHERE tenant_id=:tenant ORDER BY id LIMIT :limit",map("tenant",a.tenant().id(),"limit",max),UUID.class);}
}
